#[test]
fn unit_metadata() {
    let info = Molality::<f64>::INFO;
    assert_eq!(info.name, "Molality");
    assert_eq!(info.units.len(), MolalityUnit::ALL.len());
    for (&unit, unit_info) in MolalityUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, MolalityUnit::MolePerKilogram.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Molality::new(v, MolalityUnit::MolePerKilogram),
        Molality::from_moles_per_kilogram(v)
    );
    assert_eq!(
        Molality::from_base(v).convert_to(MolalityUnit::MolePerKilogram),
        Molality::from_base(v).as_moles_per_kilogram()
    );
    assert_eq!(
        Molality::new(v, MolalityUnit::MillimolePerKilogram),
        Molality::from_millimoles_per_kilogram(v)
    );
    assert_eq!(
        Molality::from_base(v).convert_to(MolalityUnit::MillimolePerKilogram),
        Molality::from_base(v).as_millimoles_per_kilogram()
    );
    assert_eq!(
        Molality::new(v, MolalityUnit::MolePerGram),
        Molality::from_moles_per_gram(v)
    );
    assert_eq!(
        Molality::from_base(v).convert_to(MolalityUnit::MolePerGram),
        Molality::from_base(v).as_moles_per_gram()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [Molality; 3] = [
        Molality::const_new(1234.5, MolalityUnit::MolePerKilogram),
        Molality::const_new(1234.5, MolalityUnit::MillimolePerKilogram),
        Molality::const_new(1234.5, MolalityUnit::MolePerGram),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(MolalityUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            Molality::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in MolalityUnit::ALL {
            assert_eq!(
                Molality::const_new(v, unit).as_base().to_bits(),
                Molality::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Molality::from_base(v);
        let auto = q.auto_unit();
        assert_close(Molality::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in MolalityUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Molality::from_base(0.0).auto_unit().unit,
        MolalityUnit::MolePerKilogram
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "mol/kg".parse::<MolalityUnit>(),
        Ok(MolalityUnit::MolePerKilogram)
    );
    assert_eq!(
        format!("2.5 {}", "mol/kg").parse::<Molality>(),
        Ok(Molality::new(2.5, MolalityUnit::MolePerKilogram))
    );
    assert_eq!(
        "mmol/kg".parse::<MolalityUnit>(),
        Ok(MolalityUnit::MillimolePerKilogram)
    );
    assert_eq!(
        format!("2.5 {}", "mmol/kg").parse::<Molality>(),
        Ok(Molality::new(2.5, MolalityUnit::MillimolePerKilogram))
    );
    assert_eq!(
        "mol/g".parse::<MolalityUnit>(),
        Ok(MolalityUnit::MolePerGram)
    );
    assert_eq!(
        format!("2.5 {}", "mol/g").parse::<Molality>(),
        Ok(Molality::new(2.5, MolalityUnit::MolePerGram))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Molality>(),
        Err(ParseError::UnknownUnit)
    );
}

